<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Notification\Message\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Notification\Message\Domain\ValueObject\MessageRetriesVO;

trait MessageRetriesAccessor
{
    private MessageRetriesVO $_retries;
    public function getRetries(): int
    {
        return $this->_retries->value();
    }
    public function retries(): MessageRetriesVO
    {
        return $this->_retries;
    }
    public function isRetriesChanged(?self $original = null): bool
    {
        return !$this->_retries->equals($original?->_retries);
    }
    public function withRetries(MessageRetriesVO|int $retries): self
    {
        $copy = clone $this;
        $copy->_retries = MessageRetriesVO::from($retries);
        return $copy;
    }
}
